import {useEffect,useState} from 'preact/hooks';
import {Button,Notice} from '../../components/ui.jsx';
import {compareDraft} from '../work/issue-draft.js';
import {DraftDecision} from '../work/issue-draft.jsx';
export function useAdminDraft(scope,record,fields) {
  const values=record=>Object.fromEntries(fields.map(key=>[key,record?.[key]??'']));
  const [saved,setSaved]=useState({scope,base:null,mine:values(null),latest:null});
  const state=saved.scope===scope?saved:{scope,base:null,mine:values(null),latest:null};
  const dirty=state.base?compareDraft(values(state.base),state.mine,values(state.base)).dirty:false;
  useEffect(()=>{
    if(!record)return;
    setSaved(previous=>{
      if(previous.scope!==scope||!previous.base)return {scope,base:record,mine:values(record),latest:null};
      if(previous.base.revision===record.revision)return previous;
      if(compareDraft(values(previous.base),previous.mine,values(previous.base)).dirty)return {...previous,latest:record};
      return {scope,base:record,mine:values(record),latest:null};
    });
  },[scope,record?.revision]);
  function accept(latest,mine=values(latest)){setSaved({scope,base:latest,mine,latest:null});}
  return {...state,dirty,setValues:mine=>setSaved({...state,mine}),accept,
    body:()=>({...state.mine,expectedRevision:state.base?.revision}),
    decision:{before:values(state.base),mine:state.mine,current:values(state.latest),latest:state.latest}};
}
export function AdminDraftDecision({draft,error,reload,busy}) {
  const conflict=error??(draft.latest?{status:409,message:'A newer saved version is available. Your local draft is retained.'}:null);
  return <><p>{draft.dirty?'You have unsaved local changes.':'This draft matches the saved version.'}</p>
    <Button type="button" disabled={busy} onClick={reload}>Inspect latest version</Button>
    {draft.latest&&!error&&<Notice>A newer saved version is waiting for your decision.</Notice>}
    <DraftDecision error={conflict} {...draft.decision} busy={busy} onLoad={latest=>draft.accept(latest)} onApply={(latest,mine)=>draft.accept(latest,mine)}/>
  </>;
}

import {nextPage,previousPage} from './state.js';
import {h} from 'preact';
import {useEffect,useRef,useState} from 'preact/hooks';
import {Button,Notice,Loading} from '../../components/ui.jsx';
import {createPlanningScope} from '../work/planning-actions.js';
import {useScopedLoad} from '../insight/scoped-load.js';
export function useAction(after,scope=globalThis.location?.href??'people') {
  const owner=useRef(null),callback=useRef(after);callback.current=after;
  if(!owner.current||owner.current.scope!==scope){owner.current?.lifetime.dispose();owner.current={scope,lifetime:createPlanningScope()};}
  const resource=owner.current;
  const [state,setState]=useState({resource,busy:false,error:null,message:''});
  useEffect(()=>()=>resource.lifetime.dispose(),[resource]);
  const current=operation=>owner.current===resource&&operation.current();
  async function run(fn,success='Saved.',complete) {
    const operation=resource.lifetime.begin();
    if(!operation)return null;
    setState({resource,busy:true,error:null,message:''});
    try {
      const result=await fn(operation.signal);
      if(!current(operation))return null;
      complete?.(result);
      if(!current(operation))return null;
      callback.current?.(result);
      if(current(operation))setState({resource,busy:false,error:null,message:success});
      return result;
    }catch(error){if(current(operation))setState({resource,busy:false,error,message:''});return null;}
    finally{operation.finish();}
  }
  return {...(state.resource===resource?state:{busy:false,error:null,message:''}),run,
    clear:()=>setState({resource,busy:false,error:null,message:''})};
}
export function ActionNotice({action}) {return <><Notice error={action.error}/>{action.error?.details&&<ul role="alert">{Object.entries(action.error.details).filter(([,value])=>typeof value==='string').map(([key,value])=><li>{key}: {value}</li>)}</ul>}<Notice>{action.message}</Notice></>;}
export function PageButtons({page}) {
  return <nav aria-label="List pages" className="subnav">
    <Button type="button" disabled={!page.hasBack||page.loading} onClick={page.back}>Previous page</Button>
    <span>Page {page.number}</span>
    <Button type="button" disabled={!page.nextCursor||page.loading} onClick={page.next}>Next page</Button>
  </nav>;
}
export function usePaged(api,path,limit=25) {
  const [saved,setSaved]=useState({path,history:[null]});
  const history=saved.path===path?saved.history:[null],cursor=history.at(-1);
  const identity=JSON.stringify([path,limit,cursor]);
  const result=useScopedLoad(identity,()=>api.get(path+(path.includes('?')?'&':'?')+'limit='+limit+(cursor?'&cursor='+encodeURIComponent(cursor):'')),[identity]);
  return {...result,items:result.loading?[]:result.data?.items??[],nextCursor:result.loading?null:result.data?.nextCursor,number:history.length,
    hasBack:history.length>1,next:()=>!result.loading&&result.data?.nextCursor&&setSaved({path,history:nextPage(history,result.data.nextCursor)}),
    back:()=>setSaved({path,history:previousPage(history)}),reset:()=>setSaved({path,history:[null]})};
}
export function ListState({page,children}) {
  return <><Notice error={page.error}/>{page.loading?<Loading/>:page.error?<p>Refresh after checking your current access. No previous list is shown.</p>:<>{children}<PageButtons page={page}/></>}</>;
}

import {h} from 'preact';
import {useState} from 'preact/hooks';
import {Page,Field,Button,Notice,DataTable,ConfirmButton} from '../../components/ui.jsx';
import {useScopedLoad} from '../insight/scoped-load.js';
import {useAdminDraft,AdminDraftDecision} from './drafts.jsx';
import {OrganizationLinks} from './organizations.jsx';
import {canManage,roleOptions} from './state.js';
import {usePaged,ListState,useAction,ActionNotice} from './forms.jsx';
export function Members({params,api,store}) {
  const id=params.orgId;
  const organization=useScopedLoad(id,()=>api.get('/orgs/'+id),[id]);
  const page=usePaged(api,'/orgs/'+id+'/members');
  const org=organization.data?.organization;
  const draft=useAdminDraft(id,org,['name']);
  const [values,setValues]=useState({userId:'',role:'member'});
  const action=useAction(()=>{page.reload();organization.reload();},id);
  async function rename(event) {
    event.preventDefault();
    await action.run(signal=>api.patch('/orgs/'+id,draft.body(),{signal}),'Organization renamed.',result=>{draft.accept(result.organization);store.set({organization:{...result.organization,role:org.role}});});
  }
  async function add(event) {
    event.preventDefault();await action.run(signal=>api.post('/orgs/'+id+'/members',values,{signal}),'Member added.',()=>setValues({...values,userId:''}));
  }
  const editable=member=>canManage(org?.role)&&(member.role!=='owner'||org?.role==='owner');
  return <Page title={(org?.name??'Organization')+' · Members'}>
    <OrganizationLinks id={id}/><Notice error={organization.error}/><ActionNotice action={action}/>
    <p>Your role: <strong>{org?.role??'Loading'}</strong>. Only owners manage other owners. Every organization must retain an owner.</p>
    <ListState page={page}><DataTable items={page.items} keyField="userId" columns={[
      {key:'name',label:'Name'},{key:'email',label:'Email'},
      {key:'role',label:'Role'},
      {key:'access',label:'Project access',render:member=>canManage(org?.role)&&<a href={'#/orgs/'+id+'/members/'+member.userId+'/access'}>Manage access for {member.name}</a>},
      {key:'remove',label:'Membership',render:member=>editable(member)&&<ConfirmButton busy={action.busy}
        message={`Remove ${member.name} from this organization, its teams and granted projects?`}
        onConfirm={()=>action.run(signal=>api.delete('/orgs/'+id+'/members/'+member.userId,undefined,{signal}),'Membership removed.')}>Remove</ConfirmButton>}
    ]}/></ListState>
    {canManage(org?.role)&&<>
      <h2>Add an existing account</h2><p>For new colleagues, use <a href={'#/orgs/'+id+'/invitations'}>Invitations</a>.</p>
      <form onSubmit={add}>
        <Field label="User id" required value={values.userId} onInput={e=>setValues({...values,userId:e.target.value})} error={action.error?.details?.userId}/>
        <Field label="Role" error={action.error?.details?.role}><select value={values.role} onChange={e=>setValues({...values,role:e.target.value})}>
          {roleOptions(org.role).map(role=><option>{role}</option>)}
        </select></Field><Button busy={action.busy}>Add member</Button>
      </form><h2>Rename organization</h2><form onSubmit={rename}>
        <Field label="Organization name" required maxLength={120} value={draft.mine.name} onInput={e=>draft.setValues({name:e.target.value})} error={action.error?.details?.name}/>
        <Button busy={action.busy} disabled={!draft.base||Boolean(draft.latest)}>Save name</Button>
      </form>
    </>}
    {draft.base&&<AdminDraftDecision draft={draft} error={action.error??organization.error} reload={organization.reload} busy={action.busy}/>}
  </Page>;
}

import {h} from 'preact';
import {useState} from 'preact/hooks';
import {Page,Field,Button,DataTable} from '../../components/ui.jsx';
import {organizationPath} from './state.js';
import {usePaged,ListState,useAction,ActionNotice} from './forms.jsx';
export {Members} from './members.jsx';
export {Teams,TeamDetail} from './teams.jsx';
export function OrganizationLinks({id}) {
  return <nav className="subnav" aria-label="Organization settings">
    {['members','teams','invitations','audit'].map(tab=><a href={'#'+organizationPath(id,tab)}>{tab}</a>)}
  </nav>;
}
export function Organizations({api,store,navigate}) {
  const page=usePaged(api,'/orgs');
  const [name,setName]=useState('');
  const action=useAction(result=>{store.set({organization:result.organization});navigate(organizationPath(result.organization.id));});
  async function create(event) {event.preventDefault();await action.run(signal=>api.post('/orgs',{name},{signal}),'Organization created.');}
  return <Page title="Organizations">
    <p>Choose the organization whose projects and people you want to manage.</p>
    <ActionNotice action={action}/>
    <ListState page={page}><DataTable items={page.items} empty="You have no organizations yet. Create one below." columns={[
      {key:'name',label:'Organization',render:org=><a href={'#'+organizationPath(org.id)} onClick={()=>store.set({organization:org})}>{org.name}</a>},
      {key:'role',label:'Your role'}
    ]}/></ListState>
    <h2>Create organization</h2><form onSubmit={create}>
      <Field label="Organization name" value={name} required maxLength={120} onInput={e=>setName(e.target.value)} error={action.error?.details?.name}/>
      <Button busy={action.busy}>Create organization</Button>
    </form>
  </Page>;
}

import {h} from 'preact';
import {useState} from 'preact/hooks';
import {Page,Field,Button,Notice,DataTable,ConfirmButton,Loading} from '../../components/ui.jsx';
import {useScopedLoad} from '../insight/scoped-load.js';
import {useAdminDraft,AdminDraftDecision} from './drafts.jsx';
import {OrganizationLinks} from './organizations.jsx';
import {canManage,organizationPath} from './state.js';
import {usePaged,ListState,useAction,ActionNotice} from './forms.jsx';
export function Teams({params,api}) {
  const id=params.orgId;
  const organization=useScopedLoad(id,()=>api.get('/orgs/'+id),[id]);
  const page=usePaged(api,'/orgs/'+id+'/teams');
  const [values,setValues]=useState({name:'',description:''});
  const action=useAction(()=>{page.reset();page.reload();},id);
  async function create(event) {
    event.preventDefault();await action.run(signal=>api.post('/orgs/'+id+'/teams',values,{signal}),'Team created.',()=>setValues({name:'',description:''}));
  }
  const org=organization.data?.organization;
  return <Page title={(org?.name??'Organization')+' · Teams'}>
    <OrganizationLinks id={id}/><Notice error={organization.error}/><ActionNotice action={action}/>
    <ListState page={page}><DataTable items={page.items} empty="No teams yet." columns={[
      {key:'name',label:'Team',render:team=><a href={'#/teams/'+team.id}>{team.name}</a>},{key:'description',label:'Description'}
    ]}/></ListState>
    {canManage(org?.role)&&<><h2>Create team</h2><form onSubmit={create}>
      <Field label="Team name" required maxLength={120} value={values.name} onInput={e=>setValues({...values,name:e.target.value})} error={action.error?.details?.name}/>
      <Field label="Description" error={action.error?.details?.description}><textarea value={values.description} maxLength={2000} onInput={e=>setValues({...values,description:e.target.value})}/></Field>
      <Button busy={action.busy}>Create team</Button>
    </form></>}
  </Page>;
}
export function TeamDetail({params,api,navigate}) {
  const id=params.teamId;
  const detail=useScopedLoad(id,async()=>{const team=(await api.get('/teams/'+id)).team;const org=(await api.get('/orgs/'+team.orgId)).organization;return{team,org};},[id]);
  const members=usePaged(api,'/teams/'+id+'/members');
  const team=detail.data?.team,org=detail.data?.org;
  const draft=useAdminDraft(id,team,['name','description']);
  const values=draft.mine,setValues=draft.setValues;
  const [userId,setUserId]=useState('');
  const action=useAction(()=>{members.reload();detail.reload();},id);
  const manage=canManage(org?.role);
  return <Page title={team?.name??'Team'}>
    <Notice error={detail.error}/><ActionNotice action={action}/>
    {detail.loading?<Loading/>:team&&<>
      <OrganizationLinks id={team.orgId}/><p>{team.description||'No description.'}</p>
      <ListState page={members}><DataTable items={members.items} keyField="userId" empty="This team has no members." columns={[
        {key:'name',label:'Member'},{key:'email',label:'Email'},{key:'role',label:'Organization role'},
        {key:'remove',label:'Actions',render:member=>manage&&<ConfirmButton busy={action.busy} message={'Remove '+member.name+' from this team? Organization membership is retained.'}
          onConfirm={()=>action.run(signal=>api.delete('/teams/'+id+'/members/'+member.userId,undefined,{signal}),'Team membership removed.')}>Remove</ConfirmButton>}
      ]}/></ListState>
      {manage&&<>
        <h2>Add organization member</h2><p>Browse the organization roster below to choose an account.</p>
        <MemberPicker api={api} orgId={team.orgId} value={userId} onChoose={setUserId}/>
        <form onSubmit={e=>{e.preventDefault();action.run(signal=>api.post('/teams/'+id+'/members',{userId},{signal}),'Member added to team.');}}>
          <Field label="Selected member id" required value={userId} onInput={e=>setUserId(e.target.value)} error={action.error?.details?.userId}/>
          <Button busy={action.busy} disabled={!userId}>Add to team</Button>
        </form><h2>Edit team</h2><form onSubmit={e=>{e.preventDefault();action.run(signal=>api.patch('/teams/'+id,draft.body(),{signal}),'Team saved.',result=>draft.accept(result.team));}}>
          <Field label="Name" required maxLength={120} value={values.name} onInput={e=>setValues({...values,name:e.target.value})} error={action.error?.details?.name}/>
          <Field label="Description" error={action.error?.details?.description}><textarea value={values.description} maxLength={2000} onInput={e=>setValues({...values,description:e.target.value})}/></Field>
          <Button busy={action.busy} disabled={Boolean(draft.latest)}>Save team</Button>
        </form><h2>Delete team</h2><p>Deleting a team removes its roster. Organization memberships are retained.</p>
        <ConfirmButton busy={action.busy} message={'Delete team '+team.name+' and its roster?'} onConfirm={()=>action.run(signal=>api.delete('/teams/'+id,undefined,{signal}),'Team deleted.',()=>navigate(organizationPath(team.orgId,'teams')))}>Delete team</ConfirmButton>
      </>}
    </>}
    {draft.base&&<AdminDraftDecision draft={draft} error={action.error??detail.error} reload={detail.reload} busy={action.busy}/>}
  </Page>;
}
function MemberPicker({api,orgId,value,onChoose}) {
  const page=usePaged(api,'/orgs/'+orgId+'/members',10);
  return <ListState page={page}><DataTable items={page.items} keyField="userId" columns={[
    {key:'name',label:'Name'},{key:'email',label:'Email'},
    {key:'select',label:'Choose',render:member=><Button type="button" disabled={member.userId===value} onClick={()=>onChoose(member.userId)}>{member.userId===value?'Selected':'Choose'}</Button>}
  ]}/></ListState>;
}
